import { Chess } from '../src/chess'
import { expect, test } from 'vitest'

test('all edge-rank pawn squares', () => {
  for (const color of ['w', 'b'] as const) {
    const edgeRank = color === 'w' ? '8' : '1'
    for (const f of 'abcdefgh') {
      const sq = (f + edgeRank).toLowerCase()
      const c = new Chess()
      c.clear()
      if (color === 'b') c.setTurn('b')
      c.put({ type: 'p', color }, sq as any)
      expect(() => c.moves({ square: sq as any, verbose: true })).not.toThrow()
    }
  }
  expect(true).toBe(true)
})

